  let rightEven = 0;
  let rightOdd = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) {
      rightEven += nums[i];
    } else {
      rightOdd += nums[i];
    }
  }

  let leftEven = 0;
  let leftOdd = 0;
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) {
      rightEven -= nums[i];
    } else {
      rightOdd -= nums[i];
    }
    if (leftEven + rightOdd === leftOdd + rightEven) {
      count++;
    }
    if (i % 2 === 0) {
      leftEven += nums[i];
    } else {
      leftOdd += nums[i];
    }
  }
  return count;
}

