function waysToMakeFair(nums) {
  let ways = 0;
  for (let skip = 0; skip < nums.length; skip++) {
    const rest = nums.filter((_, j) => j !== skip);
    let even = 0;
    let odd = 0;
    rest.forEach((v, j) => { if (j % 2) odd += v; else even += v; });
    if (even === odd) ways++;
  }
  return ways;
}

