function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const roll = rand();
  if (size === 'large') {
    if (roll < 0.25) {
      const value = int(1, 10000);
      return [new Array(2 * int(500, 999) + 1).fill(value)];
    }
    const top = roll < 0.65 ? 2 : 10000;
    return [Array.from({ length: int(1500, 2000) }, () => int(1, top))];
  }
  const n = int(1, 9);
  const top = roll < 0.7 ? 3 : 10;
  return [Array.from({ length: n }, () => int(1, top))];
}
